import path from "node:path";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";

/** Folder of the Postgres migrations generated by drizzle-kit (drizzle.pg.config.ts). */
export const PG_MIGRATIONS = path.resolve(process.cwd(), "drizzle-pg");

/** Applies pending migrations; drizzle records applied ones in drizzle.__drizzle_migrations, so rerunning is a no-op. */
export async function migratePg(db: NodePgDatabase<Record<string, unknown>>): Promise<void> {
  await migrate(db, { migrationsFolder: PG_MIGRATIONS });
}
